INSERT INTO skin_classification_schema.skin_conditions (code, name, category, description, common_signs) VALUES
 ('tinea_pedis', 'Athlete''s Foot (Tinea Pedis)', 'Fungal', 'Fungal infection of the feet, common with wet shoes and sweaty feet. Causes itchy, peeling skin between the toes.', ARRAY['Peeling between toes', 'Itching', 'Redness', 'Cracked skin']),
 ('tinea_capitis', 'Ringworm of the Scalp (Tinea Capitis)', 'Fungal', 'Fungal infection of the scalp, most common in school-age children. Needs medicine from a doctor.', ARRAY['Scaly bald patches', 'Itchy scalp', 'Broken hairs', 'Swollen glands']),
 ('tinea_versicolor', 'Tinea Versicolor (An-an)', 'Fungal', 'Harmless yeast overgrowth that causes light or brown patches on the chest, back and shoulders, often in hot, humid weather.', ARRAY['Light or brown patches', 'Fine scale', 'Mild itch', 'Back and chest']),
 ('tinea_cruris', 'Jock Itch (Tinea Cruris)', 'Fungal', 'Fungal rash in the groin and inner thighs, worse with sweat and tight clothing.', ARRAY['Red rash in groin', 'Itching', 'Edge is raised', 'Scaling']),
 ('onychomycosis', 'Fungal Nail Infection', 'Fungal', 'Fungus in the nails that makes them thick, yellow and brittle. Slow to clear.', ARRAY['Thick nails', 'Yellow or white nails', 'Crumbling nail', 'Nail lifting']),
 ('candidiasis', 'Skin Yeast Infection (Candidiasis)', 'Fungal', 'Yeast infection in warm skin folds such as armpits, under the breasts and the diaper area.', ARRAY['Bright red rash', 'Satellite spots', 'Itching or burning', 'Skin folds']),
 ('folliculitis', 'Folliculitis', 'Bacterial', 'Inflamed hair follicles, often after shaving, sweating or tight clothes. Looks like small red bumps or pimples around hairs.', ARRAY['Small red bumps', 'Pus-tipped bumps', 'Tenderness', 'Around hairs']),
 ('furuncle', 'Boil (Pigsa)', 'Bacterial', 'A painful, pus-filled lump under the skin, usually from a bacterial infection of a hair follicle.', ARRAY['Painful red lump', 'Pus', 'Warmth', 'Grows over days']),
 ('cellulitis', 'Cellulitis', 'Bacterial', 'A spreading bacterial infection of the deeper skin. Can become serious quickly and needs a doctor.', ARRAY['Red, hot, swollen skin', 'Pain', 'Spreading redness', 'Fever']),
 ('leprosy', 'Hansen''s Disease (Leprosy)', 'Bacterial', 'A slow-growing bacterial disease that causes pale or reddish patches with loss of feeling. It is curable with medicine from a health center.', ARRAY['Numb skin patches', 'Pale or red patches', 'Thickened nerves', 'No itching']),
 ('warts', 'Warts (Kulugo)', 'Viral', 'Rough growths caused by a virus (HPV). They often appear on the hands and feet and can spread by touch.', ARRAY['Rough bumps', 'Black dots inside', 'Hands and feet', 'Can spread']),
 ('molluscum', 'Molluscum Contagiosum', 'Viral', 'Small, smooth, pearly bumps caused by a virus, common in children. They spread by touch and usually clear by themselves.', ARRAY['Smooth round bumps', 'Dimple in centre', 'Pearly colour', 'Mild itch']),
 ('herpes_simplex', 'Cold Sores (Herpes Simplex)', 'Viral', 'Clusters of small blisters on or near the lips caused by the herpes simplex virus. They come back from time to time.', ARRAY['Tingling first', 'Small blisters', 'Crusting', 'Near the lips']),
 ('herpes_zoster', 'Shingles (Herpes Zoster)', 'Viral', 'A painful blistering rash on one side of the body from the chickenpox virus waking up. See a doctor early.', ARRAY['Burning pain', 'Blisters in a band', 'One side only', 'Itching']),
 ('chickenpox', 'Chickenpox (Bulutong)', 'Viral', 'A very itchy rash of blisters all over the body with fever, caused by a virus. It spreads easily.', ARRAY['Itchy blisters', 'Fever', 'Spots in different stages', 'Tiredness']),
 ('hfmd', 'Hand, Foot and Mouth Disease', 'Viral', 'A viral illness in young children with mouth sores and a rash on the hands and feet.', ARRAY['Mouth sores', 'Spots on palms and soles', 'Fever', 'Poor eating']),
 ('head_lice', 'Head Lice (Kuto)', 'Parasitic', 'Tiny insects living in the hair that cause an itchy scalp. They spread by close contact and shared combs.', ARRAY['Itchy scalp', 'Small white eggs on hair', 'Scratch marks', 'Behind the ears']),
 ('larva_migrans', 'Creeping Eruption (Cutaneous Larva Migrans)', 'Parasitic', 'An itchy, winding red track on the skin from animal hookworm larvae, often after walking barefoot on sand or soil.', ARRAY['Winding red line', 'Strong itch', 'Feet or buttocks', 'Moves slowly']),
 ('contact_dermatitis', 'Contact Dermatitis', 'Inflammatory', 'A rash where the skin touched something that irritates it or causes an allergy, such as soap, metal, plants or cosmetics.', ARRAY['Red itchy rash', 'Sharp edges', 'Blisters', 'Where it touched']),
 ('seborrheic_dermatitis', 'Seborrheic Dermatitis (Dandruff)', 'Inflammatory', 'Flaky, oily, red skin on the scalp, eyebrows and sides of the nose. It comes and goes.', ARRAY['Flaky scalp', 'Greasy scales', 'Red skin', 'Mild itch']),
 ('diaper_dermatitis', 'Diaper Rash', 'Inflammatory', 'Red, sore skin in the diaper area from wetness and rubbing.', ARRAY['Red skin', 'Sore to touch', 'Baby''s bottom', 'Worse when wet']),
 ('psoriasis', 'Psoriasis', 'Inflammatory', 'A long-term condition with thick, red patches covered in silvery scales, often on elbows, knees and scalp.', ARRAY['Silvery scales', 'Red thick patches', 'Elbows and knees', 'Itch or soreness']),
 ('urticaria', 'Hives (Urticaria)', 'Inflammatory', 'Raised, very itchy welts that come and go within hours, often from food, medicine, infection or stress.', ARRAY['Raised welts', 'Strong itch', 'Moves around', 'Fades in hours']),
 ('lichen_simplex', 'Lichen Simplex Chronicus', 'Inflammatory', 'Thick, leathery, itchy skin from constant scratching or rubbing in one area.', ARRAY['Thick skin', 'Intense itch', 'Scratch marks', 'One area']),
 ('nummular_eczema', 'Nummular Eczema', 'Inflammatory', 'Round, coin-shaped, itchy patches of eczema, often on the legs and arms in dry skin.', ARRAY['Coin-shaped patches', 'Itching', 'Dry crusts', 'Arms and legs']),
 ('dyshidrotic_eczema', 'Dyshidrotic Eczema', 'Inflammatory', 'Small, itchy blisters on the palms, sides of the fingers and soles.', ARRAY['Tiny blisters', 'Itching', 'Peeling', 'Hands and feet']),
 ('pityriasis_rosea', 'Pityriasis Rosea', 'Inflammatory', 'A mild rash that starts with one larger patch, then spreads in a Christmas-tree pattern on the trunk. It usually clears in 6 to 8 weeks.', ARRAY['First larger patch', 'Oval pink patches', 'Trunk', 'Mild itch']),
 ('miliaria', 'Prickly Heat (Bungang-araw)', 'Inflammatory', 'Tiny red bumps and itching from blocked sweat glands in hot, humid weather.', ARRAY['Tiny red bumps', 'Prickling itch', 'Neck and back', 'Heat and sweat']),
 ('insect_bites', 'Insect Bites', 'Inflammatory', 'Itchy red bumps from mosquitoes, fleas, bed bugs or ants. They often appear in groups.', ARRAY['Red itchy bumps', 'Groups or lines', 'Swelling', 'Scratch marks']),
 ('drug_eruption', 'Drug Rash (Medicine Allergy)', 'Inflammatory', 'A rash that appears after starting a new medicine. Stop and see a doctor straight away if there is fever, blisters or sore lips.', ARRAY['Widespread red rash', 'Itching', 'After new medicine', 'Fever (serious sign)']),
 ('rosacea', 'Rosacea', 'Inflammatory', 'Long-term redness and small bumps on the cheeks, nose and forehead that flare with heat, sun and spicy food.', ARRAY['Facial redness', 'Visible small veins', 'Red bumps', 'Flushing']),
 ('xerosis', 'Dry Skin (Xerosis)', 'Inflammatory', 'Rough, dry, flaky skin, common in older people and with frequent hot bathing.', ARRAY['Rough skin', 'Flaking', 'Tightness', 'Mild itch']),
 ('vitiligo', 'Vitiligo', 'Pigmentation', 'Smooth, milk-white patches where the skin has lost its colour. It is not contagious.', ARRAY['White patches', 'Smooth skin', 'No pain', 'Often symmetrical']),
 ('pih', 'Dark Spots After Skin Problems (Post-inflammatory Hyperpigmentation)', 'Pigmentation', 'Dark marks left after acne, bites, rashes or injuries. They fade slowly, and sun protection helps.', ARRAY['Flat dark marks', 'Where skin was inflamed', 'No pain', 'Fades slowly']),
 ('keloid', 'Keloid and Raised Scars', 'Growth', 'Scars that grow thick and raised beyond the original wound. They are more common in darker skin.', ARRAY['Raised, firm scar', 'Grows past the wound', 'Itch or tenderness', 'Shiny skin']),
 ('skin_tags', 'Skin Tags', 'Growth', 'Soft, small, harmless flaps of skin on the neck, armpits and eyelids.', ARRAY['Soft small flaps', 'Skin-coloured', 'Neck and armpits', 'Painless']),
 ('seb_keratosis', 'Seborrheic Keratosis', 'Growth', 'Harmless waxy or warty brown growths that look ''stuck on'', common with age.', ARRAY['Waxy brown growth', 'Stuck-on look', 'Rough surface', 'Painless']),
 ('nevus', 'Moles (Nevus)', 'Growth', 'Common brown or black spots. See a doctor if one changes in size, shape or colour, bleeds or has uneven edges.', ARRAY['Brown or black spot', 'Round and even', 'Stable over time', 'Warning: changes']),
 ('epidermoid_cyst', 'Skin Cyst (Epidermoid Cyst)', 'Growth', 'A slow-growing round lump under the skin with a small central pore. It can become red and painful if infected.', ARRAY['Round lump', 'Central dot', 'Slow growth', 'Painful if infected']),
 ('corns_calluses', 'Corns and Calluses', 'Growth', 'Thick, hard skin from pressure or rubbing, often on the feet and hands.', ARRAY['Thick hard skin', 'Pressure areas', 'Tender', 'Yellowish colour']),
 ('sunburn', 'Sunburn', 'Environmental', 'Red, painful skin after too much sun. Blisters or fever mean it is severe.', ARRAY['Red painful skin', 'Heat', 'Peeling later', 'Blisters if severe']),
 ('stretch_marks', 'Stretch Marks', 'Environmental', 'Thin lines or streaks after quick growth or weight change, including pregnancy. They are harmless and fade over time.', ARRAY['Thin streaks', 'Red or purple, then pale', 'Belly, thighs', 'Painless']),
 ('alopecia', 'Hair Loss (Alopecia)', 'Hair', 'Thinning hair or bald patches. Causes include stress, illness, hormones, fungal infection or autoimmune conditions.', ARRAY['Thinning hair', 'Bald patches', 'Hair on pillow', 'Scalp changes']),
 ('diabetic_foot_ulcer', 'Diabetic Foot Sore', 'Other', 'An open sore on the foot of a person with diabetes. It heals slowly and can become serious, so see a doctor soon.', ARRAY['Open sore on foot', 'Slow healing', 'Numb feet', 'Redness or smell'])
