-- DermaScreen seed: 44 more common skin conditions in the Philippines (the 6 original ones stay).
-- Safe to run twice. Run in pgAdmin as postgres. These are information entries: the photo model only
-- predicts the conditions it is trained on. Descriptions are plain-language drafts for the doctor to review.
ON CONFLICT (code) DO NOTHING;

SELECT count(*) AS total_conditions FROM skin_classification_schema.skin_conditions;